def _graph_to_json(G, path):
    from networkx.readwrite import json_graph as jg
    try:
        data = jg.node_link_data(G, edges="links")
    except TypeError:
        data = jg.node_link_data(G)
    path.write_text(json.dumps(data), encoding="utf-8")

def _make_graph(nodes, edges=None):
    """Build a simple nx.Graph from node dicts."""
    G = nx.Graph()
    for n in nodes:
        nid = n["id"]
        G.add_node(nid, **{k: v for k, v in n.items() if k != "id"})
    for e in (edges or []):
        G.add_edge(
            e["source"],
            e["target"],
            **{k: v for k, v in e.items() if k not in ("source", "target")},
        )
    return G

def _issue_fixture(base: Path) -> list[Path]:
    """The three cross-file patterns from #1356, plus a constructor-in-initializer."""
    f1 = _write(base / "Models/SessionViewModel.swift",
                "class SessionViewModel {
    func update() {}
}
")
    f2 = _write(base / "Services/NetworkService.swift",
                "class NetworkService {
    func fetch() {}
}
")
    f3 = _write(base / "Core/SessionType.swift",
                "enum SessionType {
    static func staticMethod() {}
}
")
    f4 = _write(base / "Core/Singleton.swift",
                "class Singleton {
    static let shared = Singleton()
    func method() {}
}
")
    f5 = _write(base / "Views/HomeView.swift", (
        "class HomeView {
"
        "    let vm = SessionViewModel()
"
        "    var svc: NetworkService

"
        "    func go() {
"
        "        vm.update()
"
        "        SessionType.staticMethod()
"
        "        Singleton.shared.method()
"
        "        self.svc.fetch()
"
        "    }
"
        "}
"
    ))
    return [f1, f2, f3, f4, f5]

def _label(result: dict, nid: str) -> str:
    for n in result["nodes"]:
        if n["id"] == nid:
            return n.get("label", "")
    return f"<{nid}>"
